<script setup>import {ref} from 'vue';import {Head,useForm,usePage} from '@inertiajs/vue3';import Errors from '../Components/Errors.vue';import {date} from '../lib/labels';const props=defineProps({maintenances:Array,points:Array,users:Array});const u=usePage().props.auth.user;const manager=['admin','gestionnaire'].includes(u.role),show=ref(false),f=useForm({water_point_id:'',responsible_id:'',scheduled_at:'',operations:''}),done=useForm({report:''}),editing=ref(null);</script><template><Head title="Entretiens"/><div class="page-heading heading-row"><div><span class="eyebrow">ANTICIPER POUR PRÉSERVER L’ACCÈS À L’EAU</span><h1>Entretiens préventifs</h1><p>Les visites à venir et la mémoire des opérations réalisées.</p></div><button v-if="manager" class="btn btn-primary" @click="show=!show">+ Programmer une visite</button></div><form v-if="show" class="card form-stack mb" @submit.prevent="f.post('/entretiens',{onSuccess:()=>{show=false;f.reset()}})"><Errors :errors="f.errors"/><div class="grid two"><label>Point d’eau<select v-model="f.water_point_id" required><option value="" disabled>Choisir</option><option v-for="p in points" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Responsable<select v-model="f.responsible_id" required><option value="" disabled>Choisir</option><option v-for="p in users" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div><label>Date prévue<input type="date" v-model="f.scheduled_at" required></label><label>Opérations prévues<textarea v-model="f.operations" minlength="5" required></textarea></label><button class="btn btn-primary" :disabled="f.processing">Programmer</button></form><div class="grid two"><article class="card" v-for="m in maintenances" :key="m.id"><div class="card-heading"><h3>{{m.water_point?.name}}</h3><span :class="['badge',m.completed_at?'fonctionnel':m.scheduled_at<new Date().toLocaleDateString('en-CA')?'hors_service':'planifie']">{{m.completed_at?'Réalisé':m.scheduled_at<new Date().toLocaleDateString('en-CA')?'En retard':'À venir'}}</span></div><p>{{m.operations}}</p><p class="muted mt">{{date(m.scheduled_at)}} · {{m.responsible?.name}}</p><p v-if="m.report" class="notice success">{{m.report}} · {{date(m.completed_at)}}</p><button v-if="!m.completed_at&&(manager||u.id===m.responsible_id)" class="btn btn-soft mt" @click="editing=m.id;done.reset()">Renseigner la réalisation</button><form v-if="editing===m.id" class="form-stack mt" @submit.prevent="done.post('/entretiens/'+m.id+'/terminer',{onSuccess:()=>editing=null})"><Errors :errors="done.errors"/><label>Compte rendu<textarea v-model="done.report" required minlength="5"></textarea></label><button class="btn btn-primary" :disabled="done.processing">Confirmer la réalisation</button></form></article></div><div v-if="!maintenances.length" class="card empty">Aucun entretien dans ce périmètre.</div></template>
